#!/usr/bin/env python3
# S5 fixture, NON-PRODUCTION. Throwaway prep step: parse vendomat.yaml, render .vendomat/, write only on change.
# Usage: prep.py ROOT [--force-rewrite]   prints phase timings in ms on stderr.
# Exit: 0 ok, 65 lint fault, 66 schema fault, 67 generated files stale (--check writes nothing).
import hashlib, json, os, sys, time
t0 = time.perf_counter()
sys.path.insert(0, "/home/andrew/Documents/Projects/vendomat/src")
import importlib.util
spec = importlib.util.spec_from_file_location("yamlsubset", "/home/andrew/Documents/Projects/vendomat/src/vendomat/yamlsubset.py")
ys = importlib.util.module_from_spec(spec); spec.loader.exec_module(ys)
t_import = time.perf_counter()
root = sys.argv[1]; force = "--force-rewrite" in sys.argv; check = "--check" in sys.argv
vm = open(os.path.join(root, "vendomat.yaml"), "rb").read()
try:
    data = ys.parse(vm.decode(), "vendomat.yaml")
except ys.YamlError as exc:
    print(f"vendomat: lint fault: {exc}", file=sys.stderr); sys.exit(65)
# schema stub: `packages` is a list of strings, `env` is a map of strings
pk, ev = data.get("packages", []), data.get("env", {})
if not (isinstance(pk, list) and all(isinstance(x, str) for x in pk)):
    print("vendomat: schema fault: vendomat.yaml: key 'packages': expected a list of strings", file=sys.stderr); sys.exit(66)
if not (isinstance(ev, dict) and all(isinstance(v, str) for v in ev.values())):
    print("vendomat: schema fault: vendomat.yaml: key 'env': expected a map of strings", file=sys.stderr); sys.exit(66)
t_parse = time.perf_counter()
inputs = data.pop("inputs", {}) or {}
imports = data.pop("imports", []) or []
def y(v, ind=0):
    pad = " " * ind; out = []
    if isinstance(v, dict):
        for k, x in v.items():
            if isinstance(x, (dict, list)): out.append(f"{pad}{k}:"); out += y(x, ind + 2)
            else: out.append(f"{pad}{k}: {json.dumps(x) if isinstance(x, str) else str(x).lower()}")
    else:
        for x in v: out.append(f"{pad}- {json.dumps(x)}")
    return out
yaml_text = "# GENERATED by vendomat prep. Do not edit.\n" + "\n".join(y({"inputs": inputs, "imports": imports})) + "\n"
cfg_text = json.dumps(data, sort_keys=True, indent=1) + "\n"
NIX = '''# GENERATED by vendomat prep. Do not edit.
{ lib, config, pkgs, ... }:
let
  root = config.devenv.root;
  digestText = builtins.readFile (/. + "${root}/.vendomat/digest");
  recorded = key: lib.removePrefix "${key} " (lib.findFirst (l: lib.hasPrefix "${key} " l) "${key} missing" (lib.splitString "\\n" digestText));
  cfg = builtins.fromJSON (builtins.readFile (/. + "${root}/.vendomat/config.json"));
in
{
  assertions = [
    { assertion = builtins.hashFile "sha256" (/. + "${root}/vendomat.yaml") == recorded "registry";
      message = "vendomat: vendomat.yaml changed since the last prepare. Run: vendomat shell"; }
    { assertion = builtins.hashFile "sha256" (/. + "${root}/.vendomat/devenv.yaml") == recorded "fragment";
      message = "vendomat: .vendomat/devenv.yaml was edited by hand. Run: vendomat shell"; }
  ];
  packages = map (n: pkgs.${n}) (cfg.packages or [ ]);
  env = cfg.env or { };
}
'''
h = lambda b: hashlib.sha256(b).hexdigest()
files = {".vendomat/devenv.yaml": yaml_text.encode(), ".vendomat/config.json": cfg_text.encode(), ".vendomat/devenv.nix": NIX.encode()}
digest = f"registry {h(vm)}\nfragment {h(files['.vendomat/devenv.yaml'])}\nmodule {h(files['.vendomat/devenv.nix'])}\nconfig {h(files['.vendomat/config.json'])}\n".encode()
files[".vendomat/digest"] = digest
t_render = time.perf_counter()
os.makedirs(os.path.join(root, ".vendomat"), exist_ok=True)
wrote = []
for rel, b in files.items():
    p = os.path.join(root, rel)
    try: old = open(p, "rb").read()
    except FileNotFoundError: old = None
    if (old != b or force) and check:
        wrote.append(rel)
    elif old != b or force:
        tmp = p + ".tmp"; open(tmp, "wb").write(b); os.replace(tmp, p); wrote.append(rel)
t_end = time.perf_counter()
if check:
    if wrote:
        print(f"vendomat: generated files are stale: {wrote}. Run: vendomat prepare", file=sys.stderr); sys.exit(67)
    sys.exit(0)
ms = lambda a, b: round((b - a) * 1000, 2)
print(f"prep: wrote={wrote or 'nothing'} import={ms(t0,t_import)}ms parse={ms(t_import,t_parse)}ms render={ms(t_parse,t_render)}ms compare+write={ms(t_render,t_end)}ms total={ms(t0,t_end)}ms", file=sys.stderr)
